import copy,re
from collections import defaultdict,Counter
opaque=re.compile(r'[a-z][a-z_]*-[0-9a-f]{20}')
fixed_lists={'required_roles','required_topics','required_accounts'}
def compare(a,b):
 mapping={};inverse={}
 def bind(x,y):
  if not isinstance(x,str) or not isinstance(y,str) or not opaque.fullmatch(x) or not opaque.fullmatch(y):raise ValueError('identifier syntax changed')
  if (x in mapping and mapping[x]!=y) or (y in inverse and inverse[y]!=x):raise ValueError('identifier equality changed')
  mapping[x]=y;inverse[y]=x
 def seed(x,y):
  if isinstance(x,dict):
   for k in sorted(set(x)&set(y)):
    if k in fixed_lists:
     if len(x[k])!=len(y[k]):raise ValueError('fixed membership length changed')
     for v,w in zip(x[k],y[k]):bind(v,w)
    elif isinstance(x[k],dict) and isinstance(y[k],dict):seed(x[k],y[k])
 seed(a,b)
 def walk(x,y,path=''):
  if type(x)!=type(y):raise ValueError('type changed '+path)
  if isinstance(x,dict):
   if {mapping.get(k,k) for k in x}!=set(y):raise ValueError('mapping keys changed '+path)
   for k in sorted(x):walk(x[k],y[mapping.get(k,k)],path+'/'+k)
  elif isinstance(x,list):
   if len(x)!=len(y):raise ValueError('list length changed '+path)
   for i,(v,w) in enumerate(zip(x,y)):walk(v,w,path+'/'+str(i))
  elif isinstance(x,str) and opaque.fullmatch(x):bind(x,y)
  elif x!=y:raise ValueError('non-identity fact changed '+path)
 walk(a,b)
